using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using AceEngine.Bencode;
using AceEngine.Transport;
using Xunit;

namespace AceEngine.Tests.Transport
{
    /// <summary>
    /// The files in Fixtures/ are generated by make_fixtures.py (Python + cryptography, independent of the C#).
    /// They are synthetic: there are no real Ace transport files at hand.
    /// </summary>
    public class TransportLoaderTests
    {

        private static string ExpectedValue(string file, string field)
        {
            var json = System.IO.File.ReadAllText(TestUtil.FixturePath("expected.json"));
            // Minimal JSON parser: expected.json is flat and generated by us.
            return MiniJson.Get(json, file, field);
        }

        [Theory]
        [InlineData("plain.torrent", TransportFormat.PlainBencode)]
        [InlineData("legacy_v3.acetorrent", TransportFormat.LegacyAesV3)]
        [InlineData("legacy_tslive.acetorrent", TransportFormat.LegacyAesTsLive)]
        [InlineData("legacy_v2.acetorrent", TransportFormat.LegacyAesV2)]
        public void LoadsAllLegacyFormatsWithSameTorrent(string file, TransportFormat format)
        {
            var data = TestUtil.Fixture(file);
            var tf = TransportLoader.Load(data);
            Assert.Equal(format, tf.Format);
            Assert.Equal("torrent", tf.Type);
            Assert.False(tf.IsNewFormat);
            Assert.False(tf.IsLive);
            Assert.Equal("Pack de prueba", tf.Name);
            Assert.Equal(ExpectedValue("torrent", "infohash"), tf.InfoHashHex);
            // content_id = SHA-1 of the bytes as they travel and it matches the one from sha1sum.
            Assert.Equal(ExpectedValue(file, "content_id"), tf.ContentId);
            Assert.Equal(TestUtil.Sha1Hex(data), tf.ContentId);
            Assert.Equal(data, tf.RawBytes);
            var t = tf.Torrent;
            Assert.Equal(3, t.Files.Count);
            Assert.Equal(16384, t.PieceLength);
            Assert.Equal(4, t.PieceCount);
            Assert.Equal(60037, t.TotalLength);
            Assert.Equal("Carpeta/pelicula.mp4", t.Files[0].Path);
            Assert.Equal(40000, t.Files[0].Length);
            Assert.Equal(40000 + 37, t.Files[2].Offset);
            Assert.Equal("http://tracker.example.test/announce", t.Announce);
            Assert.Equal(2, t.GetTrackerTiers().Count);
            Assert.Equal("udp://t2.example.test:6969", t.GetTrackerTiers()[1][0]);
            Assert.Equal("router.example.test", t.GetDhtNodes()[0].Key);
            Assert.Equal(6881, t.GetDhtNodes()[0].Value);
            Assert.Equal(1000000, t.XTsProperties.GetInt("bitrate"));
        }

        [Fact]
        public void PieceHashesMatchTheSyntheticContent()
        {
            var tf = TransportLoader.Load(TestUtil.Fixture("plain.torrent"));
            var content = TestUtil.Fixture("pack_content.bin");
            for (int i = 0; i < tf.Torrent.PieceCount; i++)
            {
                int len = tf.Torrent.GetPieceLength(i);
                var piece = new byte[len];
                Buffer.BlockCopy(content, i * 16384, piece, 0, len);
                Assert.Equal(TestUtil.ToHex(tf.Torrent.GetPieceHash(i)), TestUtil.Sha1Hex(piece));
            }
            Assert.Equal(60037 - 3 * 16384, tf.Torrent.GetPieceLength(3));
        }

        [Fact]
        public void LegacyIvAutoFindsSha1OfMd5Variant()
        {
            var tf = TransportLoader.Load(TestUtil.Fixture("legacy_v3_ivsha1md5.acetorrent"));
            Assert.Equal(IvMode.Sha1OfMd5Key, tf.IvUsed);
            Assert.Equal(ExpectedValue("torrent", "infohash"), tf.InfoHashHex);
        }

        [Fact]
        public void LegacyDefaultIvIsZero()
        {
            var tf = TransportLoader.Load(TestUtil.Fixture("legacy_v2.acetorrent"));
            Assert.Equal(IvMode.Zero, tf.IvUsed);
            Assert.True(tf.PaddingWasValid);
        }

        [Fact]
        public void ForcedWrongIvFailsInsteadOfGuessing()
        {
            var opt = new TransportLoadOptions { LegacyIv = IvMode.Sha1OfKey };
            Assert.Throws<TransportException>(() => TransportLoader.Load(TestUtil.Fixture("legacy_v3.acetorrent"), opt));
            var ok = TransportLoader.Load(TestUtil.Fixture("legacy_v3_ivsha1md5.acetorrent"), new TransportLoadOptions { LegacyIv = IvMode.Sha1OfMd5Key });
            Assert.Equal("Pack de prueba", ok.Name);
        }

        [Theory]
        [InlineData("live_v1.acelive", TransportFormat.AceStreamTransportV1)]
        [InlineData("live_v2.acelive", TransportFormat.AceStreamTransportV2)]
        public void LoadsLiveBtDescriptors(string file, TransportFormat format)
        {
            var data = TestUtil.Fixture(file);
            var tf = TransportLoader.Load(data);
            Assert.Equal(format, tf.Format);
            Assert.True(tf.IsNewFormat);
            Assert.True(tf.IsLive);
            Assert.Equal("bt", tf.Type);
            Assert.Equal(IvMode.Sha1OfKey, tf.IvUsed);        // confirmed
            Assert.Equal("Canal de prueba", tf.Name);
            Assert.Equal(ExpectedValue(file, "content_id"), tf.ContentId);
            var live = tf.Live;
            Assert.Equal("RSA", live.AuthMethod);
            Assert.Equal(262144, live.PieceLength);
            Assert.Equal(262144, live.ChunkLength);            // by default = piece_length
            Assert.Equal(500000, live.Bitrate);
            Assert.Equal(ExpectedValue("live", "pubkey_hex"), TestUtil.ToHex(live.PubKey));
            Assert.Equal("http://live-tracker.example.test/announce", live.Trackers.Single());
            Assert.Equal("http://mt.example.test/meta", live.MetaTrackers.Single());
            Assert.False(live.IsPrivate);
            // the descriptor's infohash = SHA1(bencode([[k, v]...])), computed separately in Python.
            Assert.Equal(ExpectedValue("live", "infohash"), tf.InfoHashHex);
        }

        [Fact]
        public void LiveInfohashRawValuesEqualAceReserialization()
        {
            var tf = TransportLoader.Load(TestUtil.Fixture("live_v2.acelive"));
            var viaRaw = LiveDescriptor.ComputeInfoHash(tf.Root, true);
            var viaReserialized = LiveDescriptor.ComputeInfoHash(tf.Root, false);
            Assert.Equal(viaRaw, viaReserialized);
        }

        [Fact]
        public void LiveIvAutoAlsoAcceptsZeroIv()
        {
            var tf = TransportLoader.Load(TestUtil.Fixture("live_v2_ivzero.acelive"));
            Assert.Equal(IvMode.Zero, tf.IvUsed);
            Assert.Equal(ExpectedValue("live", "infohash"), tf.InfoHashHex);
        }

        [Fact]
        public void MultiQualityLoadsNestedTransports()
        {
            var tf = TransportLoader.Load(TestUtil.Fixture("multi_v2.acelive"));
            Assert.True(tf.IsMulti);
            Assert.Equal("Canal multi", tf.Name);
            Assert.Equal(2, tf.Qualities.Count);
            Assert.Equal("alta", tf.Qualities[0].Name);
            Assert.Equal(ExpectedValue("live", "infohash"), tf.Qualities[0].Data.InfoHashHex);
            Assert.Equal(131072, tf.Qualities[1].Data.Live.PieceLength);
            Assert.Equal(250000, tf.Qualities[1].Data.Live.Bitrate);
            Assert.True(tf.IsLive);
            Assert.Null(tf.InfoHash);
            var q = tf.SelectQuality(0);
            Assert.Equal("Canal de prueba", q.Name);
            var mf = MediaFiles.Get(tf);                                     // multi-quality: one item per quality
            Assert.Equal(2, mf.Files.Count); Assert.Equal("alta", mf.Files[0].Filename); Assert.Equal("live", mf.Type);
        }

        [Fact]
        public void HlsDescriptorHasNoInfohash()
        {
            var tf = TransportLoader.Load(TestUtil.Fixture("hls_v1.acelive"));
            Assert.Equal("hls", tf.Type);
            Assert.Equal("Canal HLS", tf.Name);
            Assert.Null(tf.InfoHash);
            Assert.Equal(ExpectedValue("hls_v1.acelive", "content_id"), tf.ContentId);
        }

        [Fact]
        public void BuildAndLoadRoundTripForEveryFormat()
        {
            var plain = (BDict)BencodeParser.Parse(TestUtil.Fixture("plain.torrent"));
            foreach (var f in new[] { TransportFormat.PlainBencode, TransportFormat.LegacyAesV3, TransportFormat.LegacyAesTsLive, TransportFormat.LegacyAesV2 })
            {
                var bytes = TransportLoader.Build(plain, f);
                var tf = TransportLoader.Load(bytes);
                Assert.Equal(f, tf.Format);
                Assert.Equal(ExpectedValue("torrent", "infohash"), tf.InfoHashHex);
            }
            var live = (BDict)TransportLoader.Load(TestUtil.Fixture("live_v1.acelive")).Root;
            foreach (var f in new[] { TransportFormat.AceStreamTransportV1, TransportFormat.AceStreamTransportV2 })
            {
                foreach (var iv in new[] { IvMode.Zero, IvMode.Sha1OfKey, IvMode.Sha1OfMd5Key })
                {
                    var bytes = TransportLoader.Build(live, f, iv);
                    var tf = TransportLoader.Load(bytes);
                    Assert.Equal(f, tf.Format);
                    Assert.Equal(iv, tf.IvUsed);
                    Assert.Equal(ExpectedValue("live", "infohash"), tf.InfoHashHex);
                }
            }
        }

        [Fact]
        public void EightByteHeaderIsCheckedBeforeFourByteHeader()
        {
            // the 8-byte header (01020304 11026e2e) is checked before the 4-byte one (01020304).
            var data = TestUtil.Fixture("legacy_v3.acetorrent");
            Assert.Equal(TransportFormat.LegacyAesV3, TransportLoader.Load(data).Format);
        }

        [Fact]
        public void ErrorsAreReportedLikeTheOriginal()
        {
            Assert.Throws<TransportException>(() => TransportLoader.Load(new byte[0]));
            Assert.Throws<TransportException>(() => TransportLoader.Load(Encoding.ASCII.GetBytes("hola mundo")));
            // truncated AceStreamTransport (< 20 bytes)
            var ex = Assert.Throws<TransportException>(() => TransportLoader.Load(Encoding.ASCII.GetBytes("AceStreamTransport\0")));
            Assert.Contains("malformed", ex.Message);
            // unknown version
            var bad = TestUtil.Fixture("live_v2.acelive");
            bad[19] = 3;
            ex = Assert.Throws<TransportException>(() => TransportLoader.Load(bad));
            Assert.Contains("unknown transport file version", ex.Message);
            // corrupt encrypted data
            var corrupt = TestUtil.Fixture("live_v2.acelive");
            for (int i = 20; i < corrupt.Length; i++) corrupt[i] ^= 0x5a;
            Assert.Throws<TransportException>(() => TransportLoader.Load(corrupt));
            // not a multiple of 16
            var trunc = TestUtil.Fixture("live_v2.acelive");
            Array.Resize(ref trunc, trunc.Length - 3);
            Assert.Throws<TransportException>(() => TransportLoader.Load(trunc));
        }

        [Fact]
        public void BencodeWithoutInfoOrQualitiesIsNotATransport()
        {
            var ex = Assert.Throws<TransportException>(() => TransportLoader.Load(Encoding.ASCII.GetBytes("d3:fooi1ee")));
            Assert.Contains("not a transport file", ex.Message);
        }

        [Fact]
        public void LiveDescriptorMissingRequiredParamFails()
        {
            var d = new BDict();
            d.Add("name", BValue.Str("x"));
            d.Add("authmethod", BValue.Str("RSA"));
            var bytes = TransportLoader.Build(d, TransportFormat.AceStreamTransportV2, IvMode.Sha1OfKey);
            var ex = Assert.Throws<TransportException>(() => TransportLoader.Load(bytes));
            Assert.Contains("missing required param 'pubkey'", ex.Message);
        }

        [Fact]
        public void KeysAreOverridable()
        {
            var custom = Encoding.ASCII.GetBytes("otra clave");
            var d = new BDict();
            d.Add("name", BValue.Str("x")); d.Add("authmethod", BValue.Str("None"));
            d.Add("pubkey", BValue.Bytes(new byte[32])); d.Add("piece_length", BValue.Int(65536)); d.Add("bitrate", BValue.Int(100000));
            var opt = new TransportLoadOptions { KeyTransportV2 = custom };
            var bytes = TransportLoader.Build(d, TransportFormat.AceStreamTransportV2, IvMode.Sha1OfKey, opt);
            Assert.Throws<TransportException>(() => TransportLoader.Load(bytes));
            Assert.Equal("x", TransportLoader.Load(bytes, opt).Name);
        }
    }

    /// <summary>Reader of expected.json (generated by make_fixtures.py).</summary>
    internal static class MiniJson
    {
        public static string Get(string json, string obj, string field)
        {
            using (var doc = System.Text.Json.JsonDocument.Parse(json))
            {
                var v = doc.RootElement.GetProperty(obj).GetProperty(field);
                return v.ValueKind == System.Text.Json.JsonValueKind.String ? v.GetString() : v.GetRawText();
            }
        }
    }
}
